import ast
import operator
from pydantic import BaseModel, Field, model_validator, field_validator
from typing import List, Union, Literal, Dict, Optional, Any
import logging
import random
import secrets
import string

logger = logging.getLogger("PayloadEvaluator")

def safe_eval_payload(expr: str, max_length: int = 1024 * 1024 * 5):
    operators = {
        ast.Add: operator.add,
        ast.Mult: operator.mul
    }

    def _eval(node):
        if isinstance(node, ast.Constant):
            return node.value

        elif isinstance(node, ast.BinOp):
            left = _eval(node.left)
            right = _eval(node.right)

            op_type = type(node.op)
            if op_type in operators:
                if op_type == ast.Mult:

                    is_left_str = isinstance(left, str)
                    is_right_str = isinstance(right, str)
                    if is_left_str or is_right_str:

                        target_str = left if is_left_str else right
                        multiplier = right if is_left_str else left

                        if isinstance(target_str, str) and isinstance(multiplier, int):
                            if len(target_str) * multiplier > max_length:
                                raise ValueError(f"Payload result exceeds limit of {max_length} bytes")

                try:
                    return operators[op_type](left, right)
                except Exception as e:
                    raise ValueError(f"Calculation error: {e}")
            else:
                raise ValueError(f"Unsupported operator: {op_type}")

        else:
            raise ValueError(f"Unsupported syntax type: {type(node).__name__}")

    try:
        tree = ast.parse(expr, mode='eval')
        return _eval(tree.body)
    except Exception as e:
        logger.error(f"Failed to evaluate expression '{expr}': {e}")
        return expr


def expand_complex_expression(value: str) -> str:
    if not isinstance(value, str):
        return value

    if "{{" in value and "}}" in value:
        import re
        pattern = r'\{\{(.*?)\}\}'

        def replace_func(match):
            code_snippet = match.group(1).strip()
            try:
                result = safe_eval_payload(code_snippet)
                return str(result)
            except Exception as e:
                return match.group(0)
        return re.sub(pattern, replace_func, value)

    while "<<random_string>>" in value:
        length = random.randint(5, 100)
        chars = string.ascii_letters + string.digits
        rand_str = ''.join(secrets.choice(chars) for _ in range(length))
        value = value.replace("<<random_string>>", rand_str, 1)

    return value


class H3HeaderFrame(BaseModel):
    Type: Literal["headers"] = Field("headers", description="Fixed value, 'headers'")
    headers_kv: Optional[Dict[str, str]] = Field(
        None,
        description="[Recommended] Pass headers using a dictionary format, for example: {':method': 'GET', ':path': '/'}"
    )
    data_to_transfered: Optional[List[List[str]]] = Field(
        None,
        description="Internal field, typically automatically generated by headers_kv. If specified directly, it must be a two-dimensional array [[k,v], ...]"
    )

    End_Stream: bool = Field(False, description="Whether to end the stream after this frame.")

    @model_validator(mode='after')
    def process_headers(self):
        if self.headers_kv:
            self.data_to_transfered = []
            for k, v in self.headers_kv.items():
                expanded_v = expand_complex_expression(str(v))
                self.data_to_transfered.append([k, expanded_v])

        elif self.data_to_transfered:
            new_data = []
            for item in self.data_to_transfered:
                if len(item) == 2:
                    k, v = item
                    expanded_v = expand_complex_expression(str(v))
                    new_data.append([k, expanded_v])
                else:
                    new_data.append(item)
            self.data_to_transfered = new_data

        if self.data_to_transfered is None:
            self.data_to_transfered = []
        return self


class H3DataFrame(BaseModel):
    Type: Literal["data", "datagram"] = Field("data", description="usually 'data'")
    data_to_transfered: str = Field(
        ...,
        description="Raw string content of the payload. Note: Must be a string."
    )

    End_Stream: bool = Field(True, description="Whether to end the stream after this frame.")

    @field_validator('data_to_transfered', mode='before')
    def process_data(cls, v):
        return expand_complex_expression(str(v))


class H3SleepFrame(BaseModel):
    Type: Literal["sleep"] = "sleep"
    Time_to_Stop: int = Field(..., description="Pause duration (milliseconds)")

class FuzzingPayload(BaseModel):
    test_cases: Dict[str, List[Union[H3HeaderFrame, H3DataFrame, H3SleepFrame]]] = Field(
        ...,
        description="A collection of test cases. The key is the test case name (User-Agent), and the value is the list of frames."
    )


def compile_cases(cases, context):
    classes = {'headers': H3HeaderFrame, 'data': H3DataFrame,
               'datagram': H3DataFrame, 'sleep': H3SleepFrame}
    data = {}
    for case in cases:
        data[case['name']] = [classes[frame['Type']].model_validate(frame)
                              for frame in case['frames']]
    return FuzzingPayload.model_construct(test_cases=data)

"""Public sanity checker: bounded child CLI, no private inputs and no score."""
import json
import math
import os
from pathlib import Path
import selectors
import signal
import stat
import subprocess
import sys
import time

HERE = Path(__file__).resolve().parent


class CandidateFailure(Exception):
    pass


class InfrastructureError(Exception):
    pass


def unique_object(items):
    out = {}
    for k, v in items:
        if k in out:
            raise ValueError('duplicate output key')
        out[k] = v
    return out


def invalid_constant(value):
    raise ValueError('nonfinite JSON')


def finite_float(token):
    value = float(token)
    if not math.isfinite(value):
        raise ValueError('nonfinite JSON number')
    return value


def parse_output(raw):
    return json.loads(raw.decode('utf-8'), object_pairs_hook=unique_object,
                      parse_constant=invalid_constant, parse_float=finite_float)


def canonical(obj):
    return json.dumps(obj, sort_keys=True, ensure_ascii=True, separators=(',', ':'), allow_nan=False)


def storage_over_budget(scratch):
    total = entries = 0
    stack = [scratch]
    while stack:
        p = stack.pop()
        try:
            s = p.lstat()
            entries += 1
            if stat.S_ISREG(s.st_mode):
                total += max(s.st_size, s.st_blocks*512)
            elif stat.S_ISDIR(s.st_mode):
                with os.scandir(p) as children:
                    stack.extend(Path(e.path) for e in children)
        except FileNotFoundError:
            continue
        if total > 1024**3 or entries > 50000:
            return True
    return False


def invoke(candidate, raw):
    if os.geteuid() == 0:
        raise InfrastructureError('refusing root candidate execution; use the image default user')
    scratch = Path('/workspace/tmp')
    # The public image owns this dedicated directory; the private worker also
    # clears it before invocation. Only remove scratch entries, never submissions.
    import shutil
    for entry in scratch.iterdir():
        if entry.is_dir() and not entry.is_symlink():
            shutil.rmtree(entry)
        else:
            entry.unlink()
    env = {'PATH':'/usr/local/bin:/usr/bin:/bin', 'LANG':'C', 'LC_ALL':'C',
           'HOME':'/workspace', 'TMPDIR':str(scratch), 'PYTHONHASHSEED':'0',
           'PYTHONUNBUFFERED':'1', 'PYTHONDONTWRITEBYTECODE':'1',
           'OPENBLAS_NUM_THREADS':'1', 'OMP_NUM_THREADS':'1', 'MKL_NUM_THREADS':'1'}
    p = None
    sel = selectors.DefaultSelector()
    streams = []
    buffers = [bytearray(), bytearray()]
    limits = [16*1024**2, 1024**2]
    offset = 0
    deadline = time.monotonic()+60
    next_storage = 0
    try:
        previous = signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGTERM, signal.SIGINT})
        try:
            p = subprocess.Popen([sys.executable, '-I', '-B', str(HERE/'runner.py'), str(candidate)],
                                 stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                 cwd='/workspace', env=env, close_fds=True)
            streams = [p.stdin, p.stdout, p.stderr]
        finally:
            signal.pthread_sigmask(signal.SIG_SETMASK, previous)
        for stream in streams:
            os.set_blocking(stream.fileno(), False)
        if raw:
            sel.register(p.stdin, selectors.EVENT_WRITE, -1)
        else:
            p.stdin.close()
        sel.register(p.stdout, selectors.EVENT_READ, 0)
        sel.register(p.stderr, selectors.EVENT_READ, 1)
        while sel.get_map():
            now = time.monotonic()
            if now >= deadline:
                raise CandidateFailure('wall timeout')
            if now >= next_storage:
                if storage_over_budget(scratch):
                    raise InfrastructureError('scratch emergency brake; no score')
                next_storage = now+.25
            for key, _ in sel.select(min(.1, deadline-now)):
                stream, kind = key.fileobj, key.data
                if kind == -1:
                    try:
                        n = os.write(stream.fileno(), memoryview(raw)[offset:offset+65536])
                    except BlockingIOError:
                        continue
                    except BrokenPipeError:
                        sel.unregister(stream)
                        stream.close()
                        continue
                    offset += n
                    if offset == len(raw):
                        sel.unregister(stream)
                        stream.close()
                else:
                    try:
                        block = os.read(stream.fileno(), min(65536,limits[kind]-len(buffers[kind])+1))
                    except BlockingIOError:
                        continue
                    if not block:
                        sel.unregister(stream)
                        stream.close()
                    elif len(buffers[kind])+len(block) > limits[kind]:
                        raise CandidateFailure(('stdout','stderr')[kind]+' limit')
                    else:
                        buffers[kind].extend(block)
        try:
            code = p.wait(timeout=max(.001,deadline-time.monotonic()))
        except subprocess.TimeoutExpired:
            raise CandidateFailure('wall timeout') from None
        if code:
            raise CandidateFailure('nonzero exit status')
        try:
            return parse_output(bytes(buffers[0]))
        except (UnicodeError, ValueError, RecursionError):
            raise CandidateFailure('missing or malformed JSON output') from None
    finally:
        # Candidate code starts only after no-fork seccomp is installed.
        if p is not None:
            if p.poll() is None:
                p.kill()
            p.wait(timeout=5)
        sel.close()
        for stream in streams:
            stream.close()


def interrupted(signum, frame):
    signal.signal(signal.SIGTERM, signal.SIG_IGN)
    signal.signal(signal.SIGINT, signal.SIG_IGN)
    raise KeyboardInterrupt()


def main():
    for sig in (signal.SIGTERM, signal.SIGINT):
        signal.signal(sig, interrupted)
    if len(sys.argv) != 2:
        raise SystemExit('usage: python3 check.py /workspace/project')
    candidate = Path(sys.argv[1]).absolute() / 'main.py'
    s = candidate.lstat()
    if not stat.S_ISREG(s.st_mode) or s.st_nlink != 1 or s.st_size > 8*1024*1024:
        raise SystemExit('submission file must be regular, one link, at most 8 MiB')
    fixtures = json.loads((HERE/'examples.json').read_text())
    try:
        for row in fixtures:
            value = invoke(candidate, row['stdin'].encode('utf-8'))
            try:
                actual = canonical(value)
            except (ValueError, RecursionError, OverflowError):
                raise CandidateFailure('malformed JSON output') from None
            if actual != canonical(row['expected']):
                raise CandidateFailure(row['name']+': output differs from public expectation')
    except KeyboardInterrupt:
        print('INTERRUPTED: no result', file=sys.stderr)
        return 130
    except CandidateFailure as e:
        print('FAIL: '+str(e), file=sys.stderr)
        return 1
    except InfrastructureError as e:
        print('INFRASTRUCTURE ERROR: '+str(e), file=sys.stderr)
        return 2
    print('PASS: '+str(len(fixtures))+' public CLI fixtures (no score)')
    return 0


if __name__ == '__main__':
    sys.exit(main())
