    return {'n': len(data), 'h': '%016x' % hash_bytes(data)}


def _visible(data):
    for value in data:
        if not 33 <= value <= 126:
            return False
    return True


def _field_value_ok(data):
    for value in data:
        if value == HTAB:
            continue
        if not 32 <= value <= 126:
            return False
    return True


def _split_field(data):
    index = data.find(b':')
    if index <= 0:
        return None
    name = data[:index]
    if TOKEN.match(name) is None:
        return None
    value = data[index + 1:]
    if not _field_value_ok(value):
        return None
    return name, value.strip(b' \t')

