"""Origin framing and evidence audit extension.

Parses consecutive HTTP/1.1 requests out of every recorded capture channel,
attributes raw request bytes back to their producing case and derives the
paired-evidence diagnostics described by the contract.
"""
import bisect
import re

from modules.byte_program import (MAX, Cat, Lit, combine, concat_all, hash_bytes,
                                  hash_range, materialize, byte_at, window,
                                  MATERIALIZE_LIMIT)

TOKEN = re.compile(rb"[!#$%&'*+.^_`|~0-9A-Za-z-]+\Z")

CR = 13
LF = 10
SP = 32
HTAB = 9
LINE_LIMIT = 8192
BLOCK_LIMIT = 65536
FIELD_LIMIT = 128
REQUEST_LIMIT = 20000
CHUNK_LIMIT = 40000

OK = 0
SYNTAX = 1
INCOMPLETE = 2

HEXDIGITS = b'0123456789abcdefABCDEF'
DIGITS = b'0123456789'
VISIBLE = bytes(range(33, 127))
VALUE_CHARS = bytes(range(32, 127)) + bytes([9])
FORBIDDEN_TRAILER = (b'host', b'content-length', b'transfer-encoding')
LENGTH = b'content-length'
ENCODING = b'transfer-encoding'
VERSION = b'HTTP/1.1'


class Reader:
    """Logical byte stream: structural hashing plus bounded direct access."""

    __slots__ = ('node', 'length', 'data')

    def __init__(self, node):
        self.node = node
        self.length = node.length
        self.data = None
        if node.length and node.length <= MATERIALIZE_LIMIT:
            if isinstance(node, Lit):
                self.data = node.data
            else:
                self.data = materialize(node)

    def at(self, index):
        data = self.data
        return data[index] if data is not None else byte_at(self.node, index)

    def block(self, start, end):
        data = self.data
        return data[start:end] if data is not None else window(self.node, start, end)

    def find_lf(self, start, stop):
        data = self.data
        return data.find(b'\n', start, stop) if data is not None else \
            _scan_lf(self.node, start, stop)

    def region(self, start, end):
        return hash_range(self.node, start, end)

    def release(self):
        """Drop the expanded copy once the channel has been framed."""
        self.data = None


def _scan_lf(node, start, stop):
    if isinstance(node, Lit):
        return node.data.find(b'\n', start, stop)
    if start >= stop:
        return -1
    if isinstance(node, Cat):
        previous = 0
        for position, bound in enumerate(node.offsets):
            if bound <= start:
                previous = bound
                continue
            if stop <= previous:
                break
            left = max(start, previous)
            right = min(stop, bound)
            found = _scan_lf(node.parts[position], left - previous, right - previous)
            if found >= 0:
                return previous + found
            previous = bound
        return -1
    block = window(node, start, stop)
    found = block.find(b'\n')
    return -1 if found < 0 else start + found


def encode_fields(fields):
    out = bytearray(len(fields).to_bytes(8, 'big'))
    for name, value in fields:
        out += len(name).to_bytes(8, 'big')
        out += name
        out += len(value).to_bytes(8, 'big')
        out += value
    return bytes(out)


def fingerprint_bytes(data):
    return {'n': len(data), 'h': '%016x' % hash_bytes(data)}


def _visible(data):
    """Every byte is ASCII visible (33..126); C-speed set membership."""
    return not data.translate(None, VISIBLE)


def _field_value_ok(data):

    return data


def compile_document(document):
    """Validate the whole document and compile every template in it."""
    exact(document, ['seed', 'definitions', 'timeout_ms', 'cases', 'events', 'channels'])
    seed = text(document['seed'], 64)
    if SEED.match(seed) is None:
        raise ValueError('seed')
    definitions = sequence(document['definitions'], DEFINITIONS)
    for row in definitions:
        sequence(row, 2)
        if len(row) != 2:
            raise ValueError('definition pair')
        text(row[0], 32)
        text(row[1], 8192)
    context = Context(definitions, seed)
    timeout = integer(document['timeout_ms'], 1, 10 ** 9)

    cases = sequence(document['cases'], CASES)
    expectations = {}
    budget = 0
    fields_count = 0
    names = set()
    for case in cases:
        exact(case, ['name', 'frames', 'expect'])
        name = text(case['name'], 32)
        if NAME.match(name) is None or name in names:
            raise ValueError('case name')
        names.add(name)
        frames = sequence(case['frames'], SEQUENCE_ITEMS)
        budget += len(frames)
        pause_total = 0
        for frame in frames:
            if type(frame) is not dict:
                raise ValueError('frame')
            kind = frame.get('Type')
            if type(kind) is not str or kind not in ('headers', 'data', 'datagram', 'sleep'):
                raise ValueError('frame type')
            if kind == 'sleep':
                pause_total += integer(frame.get('Time_to_Stop'))
            elif kind == 'headers':
                if 'headers_kv' in frame:
                    value = frame['headers_kv']
                    fields_count += len(value) if type(value) is dict else 0
                if 'data_to_transfered' in frame:
                    value = frame['data_to_transfered']
                    if type(value) is list:
                        fields_count += len(value)
            if 'End_Stream' in frame:
                if type(frame['End_Stream']) is not bool:
                    raise ValueError('End_Stream')
            if 'Time_to_Stop' in frame and kind != 'sleep':
                raise ValueError('frame keys')
        if pause_total > MAX - timeout:
            raise ValueError('time overflow')
        exp = case['expect']
        exact(exp, ['method', 'target', 'host'])
        method = visible_ascii(exp['method'])
        visible_ascii(exp['target'])
        host = visible_ascii(exp['host'])
        if TOKEN.match(method) is None:
            raise ValueError('expected method')
        expectations[name] = {'method': method,
                              'target': visible_ascii(exp['target']),
                              'host': host.lower()}

    records = sequence(document['events'], SEQUENCE_ITEMS)
    budget += len(records)
    events = []
    for index, record in enumerate(records):
        if type(record) is not dict:
            raise ValueError('event')
        kind = record.get('kind')
        if kind not in ('close', 'headers', 'data'):
            raise ValueError('event kind')
        keys = ['at', 'kind'] if kind == 'close' else \
            ['at', 'kind', 'stream', 'end', 'fields' if kind == 'headers' else 'data']
        exact(record, keys)
        integer(record['at'])
        row = {'at': record['at'], 'kind': kind}
        if kind != 'close':
            row['stream'] = integer(record['stream'], 0, STREAM_ID)
            if type(record['end']) is not bool:
                raise ValueError('event end')
            row['end'] = record['end']
        if kind == 'headers':
            raw_fields = sequence(record['fields'], HEADER_BLOCK)
            fields_count += len(raw_fields)
            fields = []
            for position, pair in enumerate(raw_fields):
                sequence(pair, 2)
                if len(pair) != 2:
                    raise ValueError('event field pair')
                fields.append((context.template(text(pair[0]), 'event/%d/h/%d/n' % (index, position)),
                               context.template(text(pair[1]), 'event/%d/h/%d/v' % (index, position))))
            row['fields'] = fields
        elif kind == 'data':
            row['data'] = context.template(text(record['data']), 'event/%d/data' % index)
        events.append(row)

    channels = sequence(document['channels'], CHANNELS)
    channel_names = set()
    compiled_channels = []
    for index, channel in enumerate(channels):
        exact(channel, ['name', 'parts'])
        name = text(channel['name'], 32)
        if NAME.match(name) is None or name in channel_names:
            raise ValueError('channel name')
        channel_names.add(name)
        parts = sequence(channel['parts'], SEQUENCE_ITEMS)
        budget += len(parts)
        out_parts = []
        for position, part in enumerate(parts):
            exact(part, ['case', 'data'])
            owner = part['case']
            if owner is not None and (type(owner) is not str or owner not in names):
                raise ValueError('owner label')
            out_parts.append({'case': owner,
                              'data': context.template(text(part['data']),
                                                       'channel/%d/part/%d/data' % (index, position))})
        compiled_channels.append({'name': name, 'parts': out_parts})
    if budget > SEQUENCE_ITEMS or fields_count > HEADER_PAIRS:
        raise ValueError('combined budget')

    payload = compile_cases(cases, context)
    return expectations, payload.test_cases, events, compiled_channels, timeout


def run(document):
    expectations, test_cases, events, channels, timeout = compile_document(document)
    fuzzer = FuzzExecutor()
    sent = fuzzer.send_payload(test_cases, events, timeout)
    origin = audit_channels(channels, expectations, sent)
    return {'cases': sent, 'channels': origin}


def main():
    gc.disable()
    try:
        raw = sys.stdin.buffer.read(8 * 1024 ** 2 + 1)
        if len(raw) > 8 * 1024 ** 2:
            raise ValueError('input bytes')
        document = json.loads(raw.decode('utf8'), object_pairs_hook=pairs,
                              parse_constant=bad_constant, parse_float=finite_float)
        if type(document) is not dict:
            raise ValueError('document')
        result = run(document)
    except (ValueError, TypeError, KeyError, IndexError, UnicodeError, RecursionError,
            RuntimeError, OverflowError, ArithmeticError, AttributeError,
            StopIteration, NotImplementedError):
        result = {'error': 'input'}
    encoded = json.dumps(result, ensure_ascii=True, separators=(',', ':'),
                         allow_nan=False).encode('ascii')
    sys.stdout.buffer.write(encoded + b'\n')

"""Byte-sequence API for the compressed payload extension.

Sequences are kept as small expression trees so that very large logical byte
objects (repetitions of a compact literal) never need to be expanded.  Only
bounded windows are ever materialised; lengths and fingerprints are derived
algebraically from the tree shape.
"""
import ast
import bisect
import hashlib
import keyword
import re

MAX = (1 << 63) - 1
MASK = (1 << 64) - 1
BASE = 257
MODULUS = 1 << 64

NAME_SOURCE = 8192
TEMPLATE_SOURCE = 65536
MAX_DEPTH = 128

_TOKEN = re.compile(r'[A-Za-z][A-Za-z0-9_]{0,31}\Z')
RANDOM_TOKEN = '<<random_string>>'


# --------------------------------------------------------------------------- #
# fingerprints
# --------------------------------------------------------------------------- #

def hash_bytes(data):
    """Exact checksum: sum((b[i]+1)*257**(n-1-i)) mod 2**64."""
    h = 0
    for value in data:
        h = (h * BASE + value + 1) & MASK
    return h


def combine(left, right):
    """Fingerprint pair (length, hash) of a concatenation."""
    (ln, lh), (rn, rh) = left, right
    if ln == 0:
        return right
    if rn == 0:
        return left
    return (ln + rn, (lh * pow(BASE, rn, MODULUS) + rh) & MASK)


def _geom(power, count):
    """(sum(power**i for i < count) mod 2**64, power**count mod 2**64)."""
    if count <= 0:
        return 0, 1
    if count == 1:
        return 1, power % MODULUS
    if count % 2 == 0:
        half, sq = _geom(power, count // 2)
        return (half * (1 + sq)) & MASK, (sq * sq) & MASK
    total, pw = _geom(power, count - 1)
    return (total + pw) & MASK, (pw * power) & MASK


def repeat_hash(inner_hash, inner_len, count):
    """Fingerprint hash of ``inner`` repeated ``count`` times."""
    if count <= 0 or inner_len == 0:
        return 0
    return (inner_hash * _geom(pow(BASE, inner_len, MODULUS), count)[0]) & MASK


def fingerprint(node):
    if node is None:
        node = EMPTY
    return {'n': node.length, 'h': '%016x' % node.hash}


# --------------------------------------------------------------------------- #
# sequence nodes
# --------------------------------------------------------------------------- #

class Node:
    __slots__ = ('length', '_hash')

    def __init__(self, length):
        self.length = length
        self._hash = None

    @property
    def hash(self):
        h = self._hash
        if h is None:
            h = self._hash = self.compute()
        return h

    def compute(self):
        raise NotImplementedError

    def __repr__(self):
        return '%s(%d)' % (type(self).__name__, self.length)


class Lit(Node):
    __slots__ = ('data',)

    def __init__(self, data):
        super().__init__(len(data))
        self.data = data

    def compute(self):
        return hash_bytes(self.data)


class Cat(Node):
    __slots__ = ('parts', 'offsets')

    def __init__(self, parts):
        total = 0
        for part in parts:
            total += part.length
            if total > MAX:
                raise ValueError('sequence length')
        super().__init__(total)
